import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');
  const [allUsers, setAllUsers] = useState([]);
  // AI Chat
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    if (pageName === 'instructors') return 'users?role=instructor'; // NEW: Admin manages instructors
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    if (pageName === 'instructors') return { name: '', email: '', role: 'instructor', courseTitle: '' }; // Updated: Added courseTitle for create
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage(res.data.role === 'admin' ? 'instructors' : 'courses');  // Updated: Redirect admins to instructors page
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  // Assume this is the full fetchData function (from truncated code)
  const fetchData = async () => {
    setLoading(true);
    try {
      let endpoint = getEndpoint(page);
      if (page === 'courses' && user.role === 'instructor') {
        endpoint += `?instructorid=${user.id}`;
      } else if (page === 'courses' && user.role === 'student') {
        // Fetch all courses for students
        const res = await axios.get(`${API}/courses`);
        setCourses(res.data);
        setEnrolledCourseIds(res.data.filter(c => c.students.includes(user.id)).map(c => c.id));
        return;
      }
      // ... (other filters from your original code)
      const res = await axios.get(`${API}/${endpoint}`);
      setData(res.data);
    } catch (err) {
      alert('Error fetching data');
    }
    setLoading(false);
  };

  // Assume this is handleFormChange (standard)
  const handleFormChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // Assume this is handleCreateOrUpdate (from truncated)
  const handleCreateOrUpdate = async (e) => {
    e.preventDefault();
    try {
      let base = getEndpoint(page);
      if (page === 'students' || page === 'instructors') base = 'users';  // Handle users endpoint for instructors/students
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, formData);
      } else {
        await axios.post(`${API}/${base}`, formData);
      }
      setShowForm(false);
      fetchData();
    } catch (err) {
      alert('Error saving');
    }
  };

  // ... (all other functions from your original code: enroll, drop, submitAssignment, grade, delete, sendChatMessage, etc. remain unchanged)

  useEffect(() => {
    if (user && page !== 'login') fetchData();
  }, [page, user]);

  // ... (other useEffects from original remain unchanged)

  return (
    <div style={{ minHeight: '100vh', background: '#667eea', color: 'white' }}>
      {!user ? (
        <div className="container" style={{ maxWidth: '400px' }}>
          <h2>Login</h2>
          <form onSubmit={login}>
            <input
              type="email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              placeholder="Enter your email"
              style={{ width: '100%', padding: '10px', margin: '10px 0' }}
            />
            <button type="submit" className="btn">Login</button>
          </form>
        </div>
      ) : (
        <>
          <nav>
            {user.role === 'admin' ? (  // Updated: Admin-specific nav
              <>
                <button onClick={() => setPage('instructors')} className="btn">Manage Instructors</button>
              </>
            ) : (
              <>  // Original nav for student/instructor
                <button onClick={() => setPage('courses')} className="btn">Courses</button>
                <button onClick={() => setPage('assignments')} className="btn">Assignments</button>
                <button onClick={() => setPage('submissions')} className="btn">Submissions</button>
                <button onClick={() => setPage('announcements')} className="btn">Announcements</button>
                {user.role === 'instructor' && <button onClick={() => setPage('students')} className="btn">Students</button>}
              </>
            )}
            <button onClick={() => { setUser(null); setPage('login'); }} className="btn" style={{ float: 'right' }}>Logout</button>
          </nav>

          <div className="container">
            <h1>{page.charAt(0).toUpperCase() + page.slice(1)}</h1>
            {user.role === 'admin' && page === 'instructors' && (  // Admin can add instructors
              <button onClick={() => { setShowForm(true); setFormData(getEmptyForm(page)); setEditingItem(null); }} className="btn">Add Instructor</button>
            )}
            {/* ... (original table rendering for data, with columns based on page; remains unchanged) */}
            {loading ? <p>Loading...</p> : (
              <table>
                <thead>
                  <tr>{/* Headers based on page; unchanged */}</tr>
                </thead>
                <tbody>
                  {data.map(item => (
                    <tr key={item.id}>
                      {/* Cells; unchanged */}
                      <td>
                        <button onClick={() => { setEditingItem(item); setFormData(item); setShowForm(true); }} className="btn">Edit</button>
                        <button onClick={() => { setItemToDelete(item); setDeleteBase(getEndpoint(page)); setShowConfirmDelete(true); }} className="btn">Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>

          {showForm && (
            <div className="modal" style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              <div style={{ background: 'white', color: '#333', padding: '20px', borderRadius: '10px', width: '400px' }}>
                <h2>{editingItem ? 'Edit' : 'Add'} {page.charAt(0).toUpperCase() + page.slice(1).slice(0, -1)}</h2>
                <form onSubmit={handleCreateOrUpdate}>
                  {page === 'instructors' ? (  // Updated: Explicit inputs for instructors, with conditional courseTitle
                    <>
                      <label>Name</label>
                      <input name="name" value={formData.name || ''} onChange={handleFormChange} style={{ width: '100%', margin: '10px 0' }} />
                      <label>Email</label>
                      <input name="email" value={formData.email || ''} onChange={handleFormChange} style={{ width: '100%', margin: '10px 0' }} />
                      {!editingItem && (
                        <>
                          <label>Course Title (to tie to instructor)</label>
                          <input name="courseTitle" value={formData.courseTitle || ''} onChange={handleFormChange} style={{ width: '100%', margin: '10px 0' }} />
                        </>
                      )}
                    </>
                  ) : (
                    // Original form fields for other pages (loop or explicit; assuming loop from truncated)
                    Object.keys(formData).map(key => (
                      key !== 'id' && key !== 'role' && <div key={key}>
                        <label>{key}</label>
                        <input name={key} value={formData[key] || ''} onChange={handleFormChange} style={{ width: '100%', margin: '10px 0' }} />
                      </div>
                    ))
                  )}
                  <button type="submit" className="btn">Save</button>
                  <button type="button" onClick={() => setShowForm(false)} className="btn">Cancel</button>
                </form>
              </div>
            </div>
          )}

          {/* ... (all other modals: showFileModal, showGradeModal, showConfirmDelete, etc.; remain completely unchanged) */}

          {/* AI Chat (unchanged) */}
          {showChat && (
            <div style={{ position: 'fixed', bottom: '20px', right: '20px', width: '400px', height: '500px', background: 'white', borderRadius: '16px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)', display: 'flex', flexDirection: 'column', zIndex: 1000 }}>
              <div style={{ padding: '16px', background: '#667eea', color: 'white', borderRadius: '16px 16px 0 0', fontWeight: '600', fontSize: '1.1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                NM Portal Assistant
                <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', fontSize: '24px', cursor: 'pointer' }}>×</button>
              </div>
              <div style={{ flex: 1, padding: '16px', overflowY: 'auto', background: '#f8fafc' }}>
                {chatMessages.map((msg, i) => (
                  <div key={i} style={{ margin: '10px 0', textAlign: msg.sender === 'user' ? 'right' : 'left' }}>
                    <div style={{ display: 'inline-block', maxWidth: '80%', padding: '12px 16px', borderRadius: '16px', background: msg.sender === 'user' ? '#667eea' : '#e2e8f0', color: msg.sender === 'user' ? 'white' : '#333' }}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {chatLoading && <div style={{ textAlign: 'left' }}><div style={{ display: 'inline-block', padding: '12px 16px', background: '#e2e8f0', borderRadius: '16px' }}>Thinking...</div></div>}
                <div ref={chatEndRef} />
              </div>
              <div style={{ padding: '16px', borderTop: '1px solid #e2e8f0', display: 'flex' }}>
                <input
                  type="text"
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && sendChatMessage()}
                  placeholder="Ask about the portal..."
                  style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }}
                />
                <button onClick={sendChatMessage} disabled={chatLoading} style={{ marginLeft: '10px', padding: '12px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Send</button>
              </div>
            </div>
          )}
        </>
      )}
      <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
        <h3 style={{ margin: '0 0 10px' }}>Student Portal © 2025</h3>
        <p style={{ margin: 0, opacity: 0.9 }}>Nikko Manuel - Marlon Chipa Learning Management System</p>
      </footer>
    </div>
  );
}

export default App;
